//! carried, the ring words that changed), generated by
//! `python tools/fx_golden_mod2_rest.py > <this file>` from the models that match the
//! `sharc-fx` run of the firmware routines word for word
//! (`docs/research/fx-mod2-types.md`).

/// One routine's vectors.
pub(super) struct Golden {
    pub(super) ctx_in: &'static [u32],
    pub(super) frames_in: &'static [u32],
    pub(super) frames_out: &'static [u32],
    pub(super) ctx_out: &'static [u32],
    pub(super) ring_diff: &'static [(u32, u32)],
}

